- main: spawn {"func": "main::a", "handle": "ha"}; spawn {"func": "main::b", "handle": "hb"}; spawn {"func": "main::bystander", "handle": "hby"}; join {"handle": "ha"}; join {"handle": "hb"}; return {}
- a: mutex_lock {"resource": "main::a"}; semaphore_release {"resource": "main::sa"}; semaphore_acquire {"resource": "main::sb"}; mutex_unlock {"resource": "main::a"}; mutex_lock {"resource": "main::a"}; mutex_lock {"resource": "main::b"}; write_shared {"expr": "1", "resource": "main::flag"}; mutex_unlock {"resource": "main::b"}; mutex_unlock {"resource": "main::a"}; return {}
- b: mutex_lock {"resource": "main::b"}; semaphore_release {"resource": "main::sb"}; semaphore_acquire {"resource": "main::sa"}; mutex_unlock {"resource": "main::b"}; mutex_lock {"resource": "main::a"}; mutex_lock {"resource": "main::b"}; write_shared {"expr": "1", "resource": "main::flag"}; mutex_unlock {"resource": "main::b"}; mutex_unlock {"resource": "main::a"}; return {}
