    // can be moved into the spawned workers.
    let sa_holder: &'static Arc<Semaphore> = Box::leak(Box::new(Semaphore::new(1)));
    let sb_holder: &'static Arc<Semaphore> = Box::leak(Box::new(Semaphore::new(1)));
